const wo = $input.item.json.body || {};
return [{
  json: {
    workOrderId: wo.id,
    serviceCategory: 'HVAC',
    technicianPrep: 'Prepare refrigerant manifold gauges, vacuum pump, and multi-meter. Verify seasonal capacitor stock.',
    customerAdvice: 'Please ensure clear access to both indoor thermostat and outdoor condenser unit.',
    workOrder: wo
  }
}];

const wo = $input.item.json.body || {};
return [{
  json: {
    workOrderId: wo.id,
    serviceCategory: 'PLUMBING',
    technicianPrep: 'Prepare pipe inspection camera, commercial snake, and replacement shutoff valve assortment.',
    customerAdvice: 'Please locate main water shutoff valve in case isolation is required upon technician arrival.',
    workOrder: wo
  }
}];

const item = $input.item.json;
const wo = item.workOrder || {};
return [{
  json: {
    confirmationId: `conf_${wo.id || Date.now()}`,
    workOrderId: wo.id,
    serviceCategory: item.serviceCategory,
    customerNotice: {
      recipientCustomerId: wo.customerId,
      channel: 'SMS_MOCK',
      text: `DispatchAI Confirmation: Your ${item.serviceCategory} appointment is booked for ${wo.scheduledStart}. ${item.customerAdvice}`
    },
    dispatchNotice: {
      channel: 'INTERNAL_BROADCAST_MOCK',
      priority: wo.urgency,
      text: `Job #${wo.id} assigned. Tech prep: ${item.technicianPrep}`
    },
    timestamp: new Date().toISOString()
  }
}];

const payload = $input.item.json.customerNotice;
// Showcase Demo Integration: simulated external customer dispatch
return [{
  json: {
    status: 'DISPATCHED_MOCK',
    provider: 'Twilio_Mock',
    notice: payload,
    deliveredAt: new Date().toISOString()
  }
}];

const payload = $input.item.json.dispatchNotice;
// Showcase Demo Integration: simulated internal dispatch board notice
return [{
  json: {
    status: 'POSTED_MOCK',
    channel: '#field-ops-austin',
    notice: payload,
    postedAt: new Date().toISOString()
  }
}];

const conf = $('Create Confirmation').item.json;
const cust = $('Customer Notice (Demo Mock)').item.json;
const disp = $('Dispatch Notice (Demo Mock)').item.json;

return [{
  json: {
    ok: true,
    data: {
      automation: 'work-order-created-showcase',
      confirmationId: conf.confirmationId,
      workOrderId: conf.workOrderId,
      customerNoticeStatus: cust.status,
      dispatchNoticeStatus: disp.status,
      loggedAt: new Date().toISOString()
    },
    correlationId: `showcase_${Date.now()}`
  }
}];
